prompt._raw_prompt:
"{
  "图像元数据": {
    "类型": "360度等距柱状全景图",
    "投影方式": "完整球形（Equirectangular）等距柱状投影",
    "宽高比": "2:1",
    "分辨率": "超高分辨率全景，8K+"
  },
  "场景构图": {
    "地点": "偏远的、未受破坏的乡村草甸",
    "相机位置": "极低视角，贴近地面（大约15-20厘米高），仿佛置身于草丛中",
    "视野范围": "完整的水平360度，垂直180度天顶至底点",
    "投影行为": "正确的、数学上精确的等距柱状畸变，确保从底点到天顶的无缝球形拼接，无可见接缝",
    "天气状况": "清澈的春日黄昏，空气纯净",
    "景深": "浅景深（浅F-stop，如F/1.8），前景和中景焦点清晰，远景和天空完全散焦"
  },
  "视觉元素": {
    "前景（0-2米）": {
      "主体视图": "无数精致、毛茸茸的蒲公英种球（类似于参考图中的三个），它们是画面的核心焦点，被细腻的绿叶、小野花芽、嫩草茎和少量其他野花（如小黄花和紫色野豌豆）包围。这些元素在前景中占据较大的画面比例。每一个种球的纤细结构和绒毛都极其细腻，仿佛可以触摸。",
      "动态": "极轻的春风微动，几粒零星的蒲公英种子正在空中轻轻飘舞（类似于参考图中的状态）。"
    },
    "中景主体（2-10米）": {
      "地形": "起伏的草甸和低矮的灌木丛，蒲公英种球逐渐增多，形成一片花海。地面细节（草、叶）逐渐过渡为更柔和的纹理。",
      "村落": "在极远的中景（大约在90度和270度方向）有几座极小的、传统的、土坯和木质结构的古老农舍（非现代建筑），它们与环境完美融合。",
      "云雾": "无，空气清晰。"
    },
    "背景（10米-无穷大）": {
      "景观": "起伏的低山丘陵，覆盖着春天的嫩绿树林，形成一个包围式的天际线。",
      "天空": "完整的、包围式、柔焦的天空（Bokeh）。在“主体视图”方向（约0度）有强烈的、柔和的、金橙色的“黄金时刻”太阳光晕（Bokeh），正如参考图所示。这个光晕柔和地散射，延伸至约180度（反方向），那里的天空逐渐转为温暖的、柔焦的淡蓝色和粉色调。天空完全散焦成柔软、温暖的光斑。"
    },
    "环境氛围": {
      "地面半球（底点）": "完全覆盖着细腻的、低角度透视的草地、野花、落叶和蒲公英根部，形成一个完美的、无接缝的圆形底点。",
      "整体氛围": "宁静、梦幻、金色、怀旧、宏观般的细腻与无限宏大的全景视角的奇妙结合。"
    }
  },
  "渲染风格": {
    "光照": "极致温暖、金色的自然光。太阳位于主体视图方向（约0度），光线强烈且柔和地散射开来，形成包围式的光晕。中景和前景元素被温暖的背光和侧光照亮，强调其透明和纤细的质感。全景图反方向（180度）则表现出更柔和、更凉爽的余晖色调。",
    "调色": "温暖的金色和淡黄色调，与春天的嫩绿、淡蓝和粉色调平衡。高饱和度的金色，低饱和度的绿色。怀旧、柔和的电影感色调。",
    "质感质量": {
      "描述": "超高分辨率、宏观级的清晰度（针对前景物体）。蒲公英绒毛的每一根纤维都必须清晰可辨。场景整体具有柔焦和光斑（Bokeh）的艺术感。",
      "痕迹": "无人工痕迹，画面纯净，自然锐化，无过度处理。",
      "拼接": "完美的360度无缝拼接，确保在任何角度查看都不会出现断裂、拉伸或错位。"
    }
  },
  "约束条件": {
    "必须保留": [
      "纯360度全景透视，无缝拼接",
      "极低地面视角（Ground-level macro perspective）",
      "以宏观蒲公英种球为核心前景主体（参考图的扩展）",
      "金色散焦的“黄金时刻”光照（参考图的扩展）",
      "无任何现代人类活动或建筑（除了极远的古老农舍）",
      "极高的写实摄影感"
    ],
    "必须避免": [
      "城市或现代建筑",
      "人物、车辆、电线杆",
      "电影感夸张灯光、科幻或奇幻元素",
      "绘画或插画风格，必须是摄影质感",
      "非全景的普通照片布局"
    ]
  },
  "负面提示词": [
    "用户界面 (UI)",
    "抬头显示 (HUD)",
    "文本覆盖",
    "水印",
    "现代建筑",
    "桥梁",
    "行人",
    "车辆",
    "科幻艺术",
    "奇幻艺术",
    "插图",
    "过度处理",
    "边框",
    "裁剪视图",
    "全景接缝断裂",
    "底点或天顶扭曲",
    "非球形透视"
  ]
}
